def unit(v): return v/np.linalg.norm(v)

def edit_reader(conv, bn, dhat, zref, alpha):
    """Make a 1x1 reading conv blind (strength alpha) to direction dhat of its input; replace by constant zref (via BN running_mean)."""
    Wc = load(conv).double()                      # [out, in, 1, 1]  (current edit if any)
    rm = load(bn + '.running_mean').double()
    d = torch.tensor(dhat, dtype=torch.float64)
    Wd = Wc[:, :, 0, 0] @ d                         # [out]
    Wn = Wc.clone(); Wn[:, :, 0, 0] = Wc[:, :, 0, 0] - alpha*torch.outer(Wd, d)
    save_edit(conv, Wn.float()); save_edit(bn + '.running_mean', (rm - alpha*zref*Wd).float())
    return float(Wd.norm())

def edit_fc(dhat, zref, alpha, bias_shift=0.0):
    """Project direction dhat (strength alpha) out of both fc rows; constant replaced by zref via the bias; optional margin shift."""
    Wf = load('fc.weight').double(); bf = load('fc.bias').double()
    d = torch.tensor(dhat, dtype=torch.float64); Wd = Wf @ d
    Wn = Wf - alpha*torch.outer(Wd, d); bn_ = bf + alpha*zref*Wd
    bn_[1] += bias_shift/2; bn_[0] -= bias_shift/2
    save_edit('fc.weight', Wn.float()); save_edit('fc.bias', bn_.float())

